///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fnDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnDownload = async function () {
    const sbmOptions = {
        id: "tx_fnDownload",
        method: "post",
        action: "/disclosure/disclosurebystocktype.do",
        ref: "dma_fnDownloadReq",
        target: "dlt_disclosureByStockType=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jlddst00401.tx_fnDownload" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fnSearch_ajaxsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/disclosure/disclosurebystocktype.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jlddst00401.tx_fnSearch_ajaxsubmit" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.keyEvent
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.keyEvent = async function (e) {
    /* sdd-asis-lifecycle:begin keyEvent — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) == 13 || (typeof e !== 'undefined' && e == 13)) {
        if ($c.util.getKeyCode(event) == 13) {
            await scwin.fnSearchInit();
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnInit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnInit = async function () {
    /* sdd-asis-lifecycle:begin fnInit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    console.warn('[sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDatesOnlyPeriod(' + "2" + ')');
    await scwin.fnSearchInit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchInit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchInit = async function () {
    /* sdd-asis-lifecycle:begin fnSearchInit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await scwin.fnOrder("1", "D");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnOrder
 * @author Inswave
 * @date 2026. 09. 29
 * @param mode stat
 * @returns
 * @hidden N
*/
scwin.fnOrder = async function (mode, stat) {
    /* sdd-asis-lifecycle:begin fnOrder — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnDownloadReq").set("orderMode", mode);
    $c.util.getComponent("dma_fnDownloadReq").set("orderStat", stat);
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!$c.date.isDate($c.util.getComponent('cal_fromDate').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toDate').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (($c.util.getComponent('cal_fromDate').getValue() == null ? '' : String($c.util.getComponent('cal_fromDate').getValue())) !== '' && ($c.util.getComponent('cal_toDate').getValue() == null ? '' : String($c.util.getComponent('cal_toDate').getValue())) !== '') {
        if (!($c.date.diffDate($c.util.getComponent('cal_fromDate').getValue(), $c.util.getComponent('cal_toDate').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
            return;
        }
    }
    if ($c.date.addYear($c.util.getComponent('cal_fromDate').getValue(), 3) < $c.date.addYear($c.util.getComponent('cal_toDate').getValue(), 0)) {
        await $c.win.alert("조회기간은  3년 이내만 가능합니다.");
        return;
    }
    if ($(document).find("select[id=ipt_currentPageSize]").val() != null) {
        $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    }
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchDisclosureByStockTypeBenfcertSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "disclosurebystocktype_benfcert_sub");
    await scwin.tx_fnSearch_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fnSearchCallBack = function (data) {
    /* sdd-asis-lifecycle:begin fnSearchCallBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#mainContents").empty().append(data);
    $("tr:odd").addClass("active");
    console.warn('[sdd] 미실현(재설계 분류 #128): fnLegendTooltip(' + "" + ')');
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnDownload = async function () {
    /* sdd-asis-lifecycle:begin fnDownload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!$c.date.isDate($c.util.getComponent('cal_fromDate').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toDate').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (($c.util.getComponent('cal_fromDate').getValue() == null ? '' : String($c.util.getComponent('cal_fromDate').getValue())) !== '' && ($c.util.getComponent('cal_toDate').getValue() == null ? '' : String($c.util.getComponent('cal_toDate').getValue())) !== '') {
        if (!($c.date.diffDate($c.util.getComponent('cal_fromDate').getValue(), $c.util.getComponent('cal_toDate').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
            return;
        }
    }
    if ($c.date.addYear($c.util.getComponent('cal_fromDate').getValue(), 3) < $c.date.addYear($c.util.getComponent('cal_toDate').getValue(), 0)) {
        await $c.win.alert("조회기간은  3년 이내만 가능합니다.");
        return;
    }
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "3000");
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchDisclosureByStockTypeBenfcertSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "disclosurebystocktype_benfcert_down");
    await scwin.tx_fnDownload();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch1
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch1 = async function () {
    /* sdd-asis-lifecycle:begin fnSearch1 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setReportNameInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param formCd formNm
 * @returns
 * @hidden N
*/
scwin.setReportNameInfo = function (formCd, formNm) {
    /* sdd-asis-lifecycle:begin setReportNameInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_reportNm').setValue(formNm);
    /* sdd-asis-lifecycle:end */
};
